-- 22-callout-migration.sql — inline provenance markers become callout blocks.
--
-- GENERATED by scripts/generate-callout-migration.mjs from the seeded content;
-- do not edit by hand, regenerate.
--
-- The "Not yet published" and "Previous website information" notices were
-- <p class="db-pending"> and <div class="db-archive"> paragraphs typed inside
-- rich-text bodies: a convention held together by a class name that one
-- careless edit in the rich-text editor drops, silently turning a legal
-- provenance marker into an ordinary paragraph. The callout block makes the
-- tone a FIELD (lib/blocks/types/callout.js); its standard tag comes from
-- ui_strings so every notice reads the same and is edited in one place.
--
-- Two shapes were found, both identical across en/bn/zh:
--   [marker]          the block IS the notice -> its type becomes callout
--   [prose, marker]   the marker is trimmed off the body and a new callout
--                     block is inserted at the same sort_order with a higher
--                     id, so it renders directly after (order is sort_order, id)
--
-- Blocks are located by PAGE SLUG + TYPE + a run of the English marker text,
-- never by id or sort order: 02-seed.sql numbers these blocks 12, 16, 18...
-- and a re-seeded development database numbers the same blocks 135, 137,
-- 143...; 07-block-order.sql renumbers sort orders and an operator can drag a
-- block. The content is the one thing both databases share.
--
-- Every statement is guarded on the marker still being present, so a
-- re-import changes nothing and an operator's later edit is never overwritten.
-- ID map: new blocks 360+.


-- /about/governance sort 1 (source block 16): prose,legacy
SET @blk = (SELECT b.`id` FROM `blocks` b JOIN `pages` p ON p.`id` = b.`page_id`
    JOIN `block_translations` t ON t.`block_id` = b.`id` AND t.`locale` = 'en'
    WHERE p.`slug` = 'about/governance' AND b.`type` = 'rich-text'
      AND INSTR(JSON_UNQUOTE(JSON_EXTRACT(t.`data`, '$.body')), 'l 2021. The current concession terms and ownership should be checked with DBEDC.') > 0
    ORDER BY b.`id` LIMIT 1);
SET @sort = (SELECT `sort_order` FROM `blocks` WHERE `id` = @blk);
INSERT IGNORE INTO `blocks` (`id`, `page_id`, `type`, `sort_order`, `settings`, `status`)
  SELECT 360, (SELECT `id` FROM `pages` WHERE `slug` = 'about/governance' LIMIT 1), 'callout', @sort, NULL, 'published' FROM DUAL
  WHERE @blk IS NOT NULL AND EXISTS (SELECT 1 FROM `block_translations` WHERE `block_id` = @blk AND `locale` = 'en' AND JSON_UNQUOTE(JSON_EXTRACT(`data`, '$.body')) LIKE '%db-archive%');
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`)
  SELECT 360, 'en', '{"tone":"legacy","heading":"","body":"<p>Recovered from the previous website. These details may have changed and are not confirmed as current.</p><p>The previous site described a 25-year concession covering design, construction, finance, operation, maintenance and transfer. It listed the ownership as SRBG 60%, Shamim Enterprise 30% and UDC Construction 10%.</p><p>It identified China Development Bank and BIFFL as lenders and described financing agreements signed in April 2021. The current concession terms and ownership should be checked with DBEDC.</p>"}', 'published' FROM DUAL
  WHERE EXISTS (SELECT 1 FROM `block_translations` WHERE `block_id` = @blk AND `locale` = 'en' AND JSON_UNQUOTE(JSON_EXTRACT(`data`, '$.body')) LIKE '%db-archive%');
UPDATE `block_translations` SET `data` = '{"body":"<p>The Dhaka Bypass Expressway is delivered as a public–private partnership. A government contracting authority owns the corridor and sets the terms; DBEDC, as the concession company, finances, builds, operates and maintains it for a fixed term, recovers its investment through tolls, and returns the asset at the end.</p><p>That structure decides everything a road user experiences: who sets the toll, who is accountable for the road surface, and who answers a complaint.</p><p>The public partner is the Roads and Highways Department. The private consortium comprises Sichuan Road and Bridge (Group) Corporation Ltd, Shamim Enterprise (Pvt) Ltd and UDC Construction Ltd. <a href=\\"https://www.pppo.gov.bd/projects-dhaka-bypass.php\\">Source: PPPA</a>.</p>","heading":"The contractual structure"}' WHERE `block_id` = @blk AND `locale` = 'en'
  AND JSON_UNQUOTE(JSON_EXTRACT(`data`, '$.body')) LIKE '%db-archive%';
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`)
  SELECT 360, 'bn', '{"tone":"legacy","heading":"","body":"<p>আগের ওয়েবসাইট থেকে সংরক্ষিত তথ্য। এগুলি পরিবর্তিত হয়ে থাকতে পারে এবং বর্তমান তথ্য হিসেবে নিশ্চিত নয়।</p><p>আগের সাইটে নকশা, নির্মাণ, অর্থায়ন, পরিচালনা, রক্ষণাবেক্ষণ ও হস্তান্তরসহ ২৫ বছরের কনসেশনের কথা ছিল। সেখানে মালিকানা হিসেবে SRBG ৬০%, Shamim Enterprise ৩০% এবং UDC Construction ১০% উল্লেখ করা হয়েছিল।</p><p>ঋণদাতা হিসেবে China Development Bank ও BIFFL এবং এপ্রিল ২০২১-এ অর্থায়ন চুক্তির উল্লেখ ছিল। বর্তমান চুক্তির শর্ত ও মালিকানা DBEDC-এর কাছে যাচাই করুন।</p>"}', 'published' FROM DUAL
  WHERE EXISTS (SELECT 1 FROM `block_translations` WHERE `block_id` = @blk AND `locale` = 'bn' AND JSON_UNQUOTE(JSON_EXTRACT(`data`, '$.body')) LIKE '%db-archive%');
UPDATE `block_translations` SET `data` = '{"body":"<p>Dhaka Bypass Expressway সরকারি-বেসরকারি অংশীদারিত্বের (PPP) আওতায় বাস্তবায়িত হচ্ছে। সরকারি চুক্তিকারী কর্তৃপক্ষ করিডোরের মালিক এবং শর্ত নির্ধারণ করে; কনসেশন কোম্পানি হিসেবে DBEDC নির্দিষ্ট মেয়াদের জন্য অর্থায়ন, নির্মাণ, পরিচালনা ও রক্ষণাবেক্ষণ করে, টোলের মাধ্যমে বিনিয়োগ ফিরে পায় এবং মেয়াদ শেষে সম্পদ ফিরিয়ে দেয়।</p><p>সড়ক ব্যবহারকারী যা কিছু অনুভব করেন তার সবই এই কাঠামো নির্ধারণ করে — কে টোল নির্ধারণ করে, সড়কের পৃষ্ঠের জন্য কে দায়ী, এবং অভিযোগের জবাব কে দেয়।</p><p>সরকারি অংশীদার সড়ক ও জনপথ অধিদপ্তর। বেসরকারি কনসোর্টিয়ামে রয়েছে Sichuan Road and Bridge (Group) Corporation Ltd, Shamim Enterprise (Pvt) Ltd এবং UDC Construction Ltd। <a href=\\"https://www.pppo.gov.bd/projects-dhaka-bypass.php\\">সূত্র: PPPA</a>।</p>","heading":"চুক্তিগত কাঠামো"}' WHERE `block_id` = @blk AND `locale` = 'bn'
  AND JSON_UNQUOTE(JSON_EXTRACT(`data`, '$.body')) LIKE '%db-archive%';
INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`)
  SELECT 360, 'zh', '{"tone":"legacy","heading":"","body":"<p>以下内容恢复自旧版网站，可能已有变化，尚未确认为当前信息。</p><p>旧版网站描述了涵盖设计、建设、融资、运营、养护及移交的 25 年特许经营期，并列出 SRBG 持股 60%、Shamim Enterprise 持股 30%、UDC Construction 持股 10%。</p><p>旧资料将 China Development Bank 和 BIFFL 列为贷款方，并提及 2021 年 4 月签署的融资协议。当前经营条款与持股情况请向 DBEDC 核实。</p>"}', 'published' FROM DUAL
  WHERE EXISTS (SELECT 1 FROM `block_translations` WHERE `block_id` = @blk AND `locale` = 'zh' AND JSON_UNQUOTE(JSON_EXTRACT(`data`, '$.body')) LIKE '%db-archive%');
UPDATE `block_translations` SET `data` = '{"body":"<p>Dhaka Bypass Expressway 采用政府与社会资本合作（PPP）模式实施。政府签约机构拥有该走廊并确定各项条件；DBEDC 作为特许经营公司，在约定期限内负责融资、建设、运营与养护，通过收取通行费回收投资，期满后移交资产。</p><p>道路使用者所感受到的一切都由这一架构决定：由谁制定收费标准、由谁对路面状况负责、以及由谁答复投诉。</p><p>公共合作方为公路局（RHD），私人联合体由 Sichuan Road and Bridge (Group) Corporation Ltd、Shamim Enterprise (Pvt) Ltd 和 UDC Construction Ltd 组成。<a href=\\"https://www.pppo.gov.bd/projects-dhaka-bypass.php\\">来源：PPPA</a>。</p>","heading":"合同架构"}' WHERE `block_id` = @blk AND `locale` = 'zh'
  AND JSON_UNQUOTE(JSON_EXTRACT(`data`, '$.body')) LIKE '%db-archive%';

