  SELECT 361, 'en', '{"tone":"legacy","heading":"","body":"<p>Recovered from the previous website. These details may have changed and are not confirmed as current.</p><p><strong>Construction snapshot dated 31 December 2024:</strong> the previous project page reported overall progress of 69.11%, earthworks at 82.89%, pavement at 53.95%, foundations at 100% and structures at 90.9%.</p><p>It described an initial project investment of US$412 million and an appointed date of 15 May 2022. These are figures reported by the previous site, not an updated financial statement.</p><p>The old July 2025 and December 2025 opening targets are historical targets that have passed. They do not indicate that the remaining road is open. Use the route map for the published operating status.</p>"}', 'published' FROM DUAL
