UPDATE `block_translations` SET `data` = '{"body":"<p>Project history: the PPP contract was signed on 6 December 2018. BIFFL reports that its first loan disbursement to the project was made in April 2022. These are historical milestones, separate from the road’s current operating status. <a href=\\"https://www.pppo.gov.bd/projects-dhaka-bypass.php\\">PPPA project profile</a>; <a href=\\"https://www.biffl.org.bd/uploads/images/reports/BIFFL%20Annual%20Report%202022%20Final%20Update.pdf\\">BIFFL annual report 2022, page 88</a>.</p>","heading":"Programme and cost"}' WHERE `block_id` = @blk AND `locale` = 'en'
