INSERT IGNORE INTO `block_translations` (`block_id`, `locale`, `data`, `status`)
  SELECT 361, 'bn', '{"tone":"legacy","heading":"","body":"<p>আগের ওয়েবসাইট থেকে সংরক্ষিত তথ্য। এগুলি পরিবর্তিত হয়ে থাকতে পারে এবং বর্তমান তথ্য হিসেবে নিশ্চিত নয়।</p><p><strong>৩১ ডিসেম্বর ২০২৪-এর নির্মাণ চিত্র:</strong> আগের প্রকল্প পাতায় সার্বিক অগ্রগতি ৬৯.১১%, মাটির কাজ ৮২.৮৯%, পেভমেন্ট ৫৩.৯৫%, ভিত্তি ১০০% ও অবকাঠামো ৯০.৯% বলা হয়েছিল।</p><p>প্রাথমিক প্রকল্প বিনিয়োগ ৪১২ মিলিয়ন মার্কিন ডলার এবং নির্ধারিত সূচনার তারিখ ১৫ মে ২০২২ উল্লেখ ছিল। এগুলি আগের সাইটের তথ্য, হালনাগাদ আর্থিক বিবরণী নয়।</p><p>জুলাই ও ডিসেম্বর ২০২৫-এর পুরোনো উদ্বোধনের লক্ষ্য ইতোমধ্যে পেরিয়ে গেছে। এগুলি অবশিষ্ট সড়ক খোলা থাকার প্রমাণ নয়। প্রকাশিত পরিচালনার অবস্থা রুট মানচিত্রে দেখুন।</p>"}', 'published' FROM DUAL
