UPDATE `block_translations` SET `data` = '{"body":"<p>প্রকল্পের ইতিহাস: ৬ ডিসেম্বর ২০১৮ PPP চুক্তি স্বাক্ষরিত হয়। BIFFL-এর প্রতিবেদন অনুযায়ী প্রকল্পে তাদের প্রথম ঋণ বিতরণ হয় এপ্রিল ২০২২-এ। এগুলি ঐতিহাসিক মাইলফলক, বর্তমান সড়ক পরিচালনার অবস্থা নয়। <a href=\\"https://www.pppo.gov.bd/projects-dhaka-bypass.php\\">PPPA প্রকল্প পরিচিতি</a>; <a href=\\"https://www.biffl.org.bd/uploads/images/reports/BIFFL%20Annual%20Report%202022%20Final%20Update.pdf\\">BIFFL বার্ষিক প্রতিবেদন ২০২২, পৃষ্ঠা ৮৮</a>।</p>","heading":"কর্মসূচি ও ব্যয়"}' WHERE `block_id` = @blk AND `locale` = 'bn'
  AND JSON_UNQUOTE(JSON_EXTRACT(`data`, '$.body')) LIKE '%db-archive%';
